use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// The hosts this node is granted. Checked before every fetch so that an
/// out-of-scope URL is recorded as a failure instead of reaching the
/// boundary, where it would trap the whole run.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extract the host from an `https://` URL. Returns `None` for anything
/// ambiguous: a missing scheme, IPv6 literals, multiple colons, or an empty host.
fn host_of(url: &str) -> Option<&str> {
    let rest = url.strip_prefix("https://")?;
    let end = rest.find(['/', '?', '#']).unwrap_or(rest.len());
    let authority = &rest[..end];

    // Drop userinfo: everything up to the last '@'.
    let hostport = match authority.rfind('@') {
        Some(i) => &authority[i + 1..],
        None => authority,
    };

    if hostport.is_empty() || hostport.contains('[') || hostport.matches(':').count() > 1 {
        return None;
    }

    // Drop an optional port.
    let host = hostport.split(':').next()?;
    if host.is_empty() {
        None
    } else {
        Some(host)
    }
}

fn allowed(host: &str) -> bool {
    ALLOWED_HOSTS.iter().any(|h| h.eq_ignore_ascii_case(host))
}

struct Node;

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for url in subscriptions.urls {
            let in_scope = host_of(&url).map_or(false, allowed);

            if !in_scope {
                failures.push(FetchFailure {
                    url,
                    error: "host not in allowlist".to_string(),
                });
                continue;
            }

            // `fetch` returns transport failures as values, so one dead feed
            // does not fail the run.
            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
